mapper.select:
SELECT PRODID, prodName, raisemode, VDATE, MDATE, raiseType, IVSTORIENTATION, ccy, operateMode, opentype, term, termtype, isTransfer, isBreakeven, isFhxgcp, excFinSector, isYllccp, isThisTrem, isEndTrem, sum(endamtsumOth) endamtsumOth, sum(payamtsum) payamtsum, sum(customeramt) customeramt, sum(bankamt) bankamt, sum(dirtyamtsum) dirtyamtsum, sum(cleanamtsum) cleanamtsum, sum(ordIdentified01) ordIdentified01, sum(ordIdentified02) ordIdentified02, sum(ordIdentified03) ordIdentified03, sum(ordIdentified04) ordIdentified04, sum(ordIdentified05) ordIdentified05, sum(ordIdentified06) ordIdentified06, sum(ordIdentified07) ordIdentified07, sum(ordIdentified08) ordIdentified08, sum(ordIdentified09) ordIdentified09 FROM ( SELECT P.POSUUID, P.PRODID, B.PROD_NAME prodName, P.RAISEMODE raisemode, B.VDATE, B.MDATE, B.raise_type raiseType, B.IVSTORIENTATION, P.ccy, B.OPERATE_MODE operateMode, CASE WHEN B.OPERATE_MODE = '03' THEN CASE WHEN B.cash_mana_cate = '01' THEN '01' WHEN B.termtype IN ('06','08','09') THEN '02' ELSE '99' END END opentype, P.TERMDAYS term, P.termtype, b.is_transfer isTransfer, case b.profit_type when '03' then '02' else '01' end isBreakeven, ifnull(b.is_fhxgcp,'01') isFhxgcp, B.exc_fin_sector excFinSector, case when instr(cpdi.prd_spec_property ,'01')>0 then '01' else '02' end isYllccp , p.dirtyamtsum, p.cleanamtsum, CASE WHEN DATE_FORMAT(B.VDATE,'%Y%m') = P.TERM then '01' else '02' end isThisTrem, case P.DURATIONFLAG when '02' then '02' else '01' end isEndTrem, P.ENDAMTSUM_OTH endamtsumOth, P.PAYAMTSUM payamtsum, P.CUSTOMERAMT customeramt, P.BANKAMT bankamt, case when ORD_IDENTIFIED = '01' then P.ENDAMTSUM_OTH end as ordIdentified01, case when ORD_IDENTIFIED = '02' then P.ENDAMTSUM_OTH end as ordIdentified02, case when ORD_IDENTIFIED = '03' then P.ENDAMTSUM_OTH end as ordIdentified03, case when ORD_IDENTIFIED = '05' then P.ENDAMTSUM_OTH end as ordIdentified04, case when ORD_IDENTIFIED = '06' then P.ENDAMTSUM_OTH end as ordIdentified05, case when ORD_IDENTIFIED = '07' then P.ENDAMTSUM_OTH end as ordIdentified06, case when ORD_IDENTIFIED = '08' then P.ENDAMTSUM_OTH end as ordIdentified07, case when ORD_IDENTIFIED = '04' then P.ENDAMTSUM_OTH end as ordIdentified08, case when ORD_IDENTIFIED = '09' then P.ENDAMTSUM_OTH end as ordIdentified09
FROM CHB_MONTH_PRD_POSITIONDETAIL P LEFT JOIN CHB_PRD_BASEINFO B ON P.PRODID= b.Prod_Id AND B.FPROD_ID IS NULL AND B.STATUS IN ('E','M') LEFT JOIN CHB_PRD_DECLARE_INFO CPDI ON P.PRODID= CPDI.PROD_INS_ID AND CPDI.STATUS IN ('E','M') WHERE 1=1
and P.TERM = #{enddate,jdbcType=VARCHAR}
#{item}
) A
GROUP BY PRODID, prodName, raisemode, VDATE, MDATE, raiseType, IVSTORIENTATION, ccy, operateMode, opentype, term, termtype, isTransfer, isBreakeven, isFhxgcp, excFinSector, isYllccp, isThisTrem, isEndTrem
